from __future__ import annotations

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


try:
    import ledger  # type: ignore
except Exception:  # pragma: no cover
    ledger = None  # type: ignore


class _PostError(Exception):
    pass


def _post_error_type():
    if ledger is not None and hasattr(ledger, "PostError"):
        return ledger.PostError
    return _PostError


def encode_amount(dollars: str) -> str:
    """
    Encode a dollar amount string into the team's wire format: signed integer cents.

    Examples:
        "12.30" -> "1230"
        "-0.07" -> "-7"
    """
    if not isinstance(dollars, str):
        raise _post_error_type()("malformed amount")

    text = dollars.strip()
    if not text:
        raise _post_error_type()("malformed amount")

    try:
        amount = Decimal(text)
    except (InvalidOperation, ValueError):
        raise _post_error_type()("malformed amount")

    if not amount.is_finite():
        raise _post_error_type()("malformed amount")

    cents_decimal = (amount * Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP)

    if cents_decimal != amount * Decimal("100"):
        raise _post_error_type()("malformed amount")

    cents = int(cents_decimal)
    return str(cents)

